using System;
using System.Collections.Generic;
using FOC.Domain.Characters;
using FOC.Domain.Cities;
using FOC.Domain.Common;
using FOC.Domain.Diplomacy;
using FOC.Domain.Time;

namespace FOC.Application.Save
{
    public static partial class CampaignSaveMapper
    {
        private static void AddDiplomacySaveData(FOC.Domain.Campaign.CampaignRuntimeState state,CampaignSaveData data)
        {
            foreach(var x in state.Diplomacy.Actors.OrderedActors)data.DiplomaticActors.Add(new DiplomaticActorSaveData{FactionId=x.Id.Value,Name=x.Name,Lifecycle=(int)x.Lifecycle});foreach(var x in state.Diplomacy.Relations.OrderedRelations){var d=new DiplomaticRelationSaveData{FirstActorId=x.Pair.First.Value,SecondActorId=x.Pair.Second.Value,Disposition=(int)x.Disposition,UpdatedAt=x.UpdatedAt.Ticks};foreach(var f in x.OrderedFactors)d.Factors.Add(new DiplomaticFactorSaveData{SourceId=f.SourceId,Source=(int)f.Source,Direction=(int)f.Direction,OccurredAt=f.OccurredAt.Ticks});data.DiplomaticRelations.Add(d);}foreach(var x in state.Diplomacy.Missions.OrderedMissions){var d=new EnvoyMissionSaveData{EnvoyMissionId=x.Id.Value,CharacterId=x.CharacterId.Value,OrganizationId=x.OrganizationId.Value,AssignmentId=x.AssignmentId.Value,SourceActorId=x.SourceActorId.Value,TargetActorId=x.TargetActorId.Value,MissionType=(int)x.MissionType,AuthorityScope=(int)x.Mandate.Scope,CreatedAt=x.CreatedAt.Ticks,DepartedAt=x.DepartedAt?.Ticks,ArrivedAt=x.ArrivedAt?.Ticks,CompletedAt=x.CompletedAt?.Ticks,Phase=(int)x.Phase};foreach(var a in x.Mandate.OrderedAllowedActions)d.AllowedActions.Add((int)a);data.EnvoyMissions.Add(d);}foreach(var x in state.Diplomacy.Messages.OrderedMessages)data.DiplomaticMessages.Add(new DiplomaticMessageSaveData{DiplomaticMessageId=x.Id.Value,SenderActorId=x.SenderActorId.Value,RecipientActorId=x.RecipientActorId.Value,Kind=(int)x.Kind,CarrierKind=(int)x.CarrierKind,CarrierCharacterId=x.CarrierCharacterId.Value,EnvoyMissionId=x.EnvoyMissionId?.Value??string.Empty,ResponseToId=x.ResponseTo?.Value??string.Empty,CreatedAt=x.CreatedAt.Ticks,DispatchedAt=x.DispatchedAt?.Ticks,DeliveredAt=x.DeliveredAt?.Ticks,Status=(int)x.Status});foreach(var x in state.Diplomacy.Actions.OrderedActions)data.DiplomaticActions.Add(new DiplomaticActionSaveData{DiplomaticActionId=x.Id.Value,SourceActorId=x.SourceActorId.Value,TargetActorId=x.TargetActorId.Value,Kind=(int)x.Kind,EnvoyMissionId=x.MissionId.Value,DiplomaticMessageId=x.MessageId.Value,OrderedAt=x.OrderedAt.Ticks,Status=(int)x.Status,Outcome=x.Outcome.HasValue?(int?)x.Outcome.Value:null,ResolvedAt=x.ResolvedAt?.Ticks});foreach(var x in state.Diplomacy.Reports.OrderedReports){var d=new ReportSaveData{ReportId=x.Id.Value,Type=(int)x.Type,SourceKind=(int)x.Source.Kind,SourceId=x.Source.Id,SourceCityId=x.Source.CityId?.Value??string.Empty,SourceBuildingId=x.Source.BuildingId?.Value??string.Empty,RecipientActorId=x.RecipientActorId.Value,Quality=(int)x.Quality,DetailLevel=(int)x.DetailLevel,ObservedAt=x.ObservedAt.Ticks,DispatchedAt=x.DispatchedAt?.Ticks,ArrivedAt=x.ArrivedAt?.Ticks,Status=(int)x.Status};foreach(var o in x.OrderedObservations)d.Observations.Add(new ReportObservationSaveData{SubjectKind=(int)o.Subject.Kind,SubjectId=o.Subject.Id,Kind=(int)o.Kind,Precision=(int)o.Precision,Lower=o.Lower,Upper=o.Upper,Qualitative=(int)o.Qualitative});data.Reports.Add(d);}foreach(var x in state.Diplomacy.Information.OrderedInformation){var d=new ActorInformationSaveData{ActorId=x.ActorId.Value};foreach(var r in x.OrderedAvailableReports)d.AvailableReportIds.Add(r.Id.Value);data.ActorInformation.Add(d);}foreach(var x in state.Diplomacy.Agreements.OrderedAgreements){var d=new DiplomaticAgreementSaveData{AgreementId=x.Id.Value,FirstActorId=x.Parties.First.Value,SecondActorId=x.Parties.Second.Value,Kind=(int)x.Kind,SignedAt=x.SignedAt.Ticks,EffectiveAt=x.EffectiveAt.Ticks,ExpiresAt=x.ExpiresAt?.Ticks,Status=(int)x.Status};foreach(var t in x.OrderedTerms)d.Terms.Add((int)t);data.DiplomaticAgreements.Add(d);}
        }
        private static DiplomacyState RestoreDiplomacy(CampaignSaveData data)
        {
            var d=new DiplomacyState();foreach(var x in data.DiplomaticActors)d.Actors.Add(new DiplomaticActorState(FactionId.Create(x.FactionId),x.Name,(DiplomaticActorLifecycle)x.Lifecycle));foreach(var x in data.DiplomaticRelations){var relation=new DiplomaticRelationState(new DiplomaticActorPair(FactionId.Create(x.FirstActorId),FactionId.Create(x.SecondActorId)),(DiplomaticDisposition)x.Disposition,new WorldTimestamp(x.UpdatedAt));foreach(var f in x.Factors)relation.AddFactor(new DiplomaticFactor(f.SourceId,(DiplomaticFactorSource)f.Source,(DiplomaticFactorDirection)f.Direction,new WorldTimestamp(f.OccurredAt)));d.Relations.Add(relation);}foreach(var x in data.EnvoyMissions){var allowed=new List<DiplomaticActionKind>();foreach(var a in x.AllowedActions)allowed.Add((DiplomaticActionKind)a);d.Missions.Add(new EnvoyMissionState(EnvoyMissionId.Create(x.EnvoyMissionId),CharacterId.Create(x.CharacterId),OrganizationId.Create(x.OrganizationId),AssignmentId.Create(x.AssignmentId),FactionId.Create(x.SourceActorId),FactionId.Create(x.TargetActorId),(EnvoyMissionType)x.MissionType,new DiplomaticMandate((DiplomaticAuthorityScope)x.AuthorityScope,allowed),new WorldTimestamp(x.CreatedAt),(EnvoyMissionPhase)x.Phase,Ts(x.DepartedAt),Ts(x.ArrivedAt),Ts(x.CompletedAt)));}foreach(var x in data.DiplomaticMessages)d.Messages.Add(new DiplomaticMessageState(DiplomaticMessageId.Create(x.DiplomaticMessageId),FactionId.Create(x.SenderActorId),FactionId.Create(x.RecipientActorId),(MessageKind)x.Kind,(MessageCarrierKind)x.CarrierKind,CharacterId.Create(x.CarrierCharacterId),new WorldTimestamp(x.CreatedAt),string.IsNullOrEmpty(x.EnvoyMissionId)?(EnvoyMissionId?)null:EnvoyMissionId.Create(x.EnvoyMissionId),(CommunicationStatus)x.Status,Ts(x.DispatchedAt),Ts(x.DeliveredAt),string.IsNullOrEmpty(x.ResponseToId)?(DiplomaticMessageId?)null:DiplomaticMessageId.Create(x.ResponseToId)));foreach(var x in data.DiplomaticActions)d.Actions.Add(new DiplomaticActionState(DiplomaticActionId.Create(x.DiplomaticActionId),FactionId.Create(x.SourceActorId),FactionId.Create(x.TargetActorId),(DiplomaticActionKind)x.Kind,EnvoyMissionId.Create(x.EnvoyMissionId),DiplomaticMessageId.Create(x.DiplomaticMessageId),new WorldTimestamp(x.OrderedAt),(DiplomaticActionStatus)x.Status,x.Outcome.HasValue?(DiplomaticActionOutcome?)x.Outcome.Value:null,Ts(x.ResolvedAt)));foreach(var x in data.Reports){var obs=new List<ReportObservation>();foreach(var o in x.Observations)obs.Add(new ReportObservation(new ReportSubjectRef((ReportSubjectKind)o.SubjectKind,o.SubjectId),(ReportObservationKind)o.Kind,(ObservationPrecision)o.Precision,o.Lower,o.Upper,(QualitativeObservation)o.Qualitative));d.Reports.Add(new ReportState(ReportId.Create(x.ReportId),(ReportType)x.Type,RestoreReportSource(x),FactionId.Create(x.RecipientActorId),(ReportQuality)x.Quality,(ReportDetailLevel)x.DetailLevel,new WorldTimestamp(x.ObservedAt),obs,(CommunicationStatus)x.Status,Ts(x.DispatchedAt),Ts(x.ArrivedAt)));}foreach(var x in data.ActorInformation){var info=new ActorInformationState(FactionId.Create(x.ActorId));foreach(var id in x.AvailableReportIds)info.RestoreAvailable(d.Reports.GetRequired(ReportId.Create(id)));d.Information.Add(info);}foreach(var x in data.DiplomaticAgreements){var terms=new List<DiplomaticAgreementTerm>();foreach(var t in x.Terms)terms.Add(new DiplomaticAgreementTerm((DiplomaticAgreementTermKind)t));d.Agreements.Add(new DiplomaticAgreementState(DiplomaticAgreementId.Create(x.AgreementId),new DiplomaticActorPair(FactionId.Create(x.FirstActorId),FactionId.Create(x.SecondActorId)),(DiplomaticAgreementKind)x.Kind,new WorldTimestamp(x.SignedAt),new WorldTimestamp(x.EffectiveAt),terms,Ts(x.ExpiresAt),(DiplomaticAgreementStatus)x.Status));}return d;
        }
        private static WorldTimestamp? Ts(long? x)=>x.HasValue?(WorldTimestamp?)new WorldTimestamp(x.Value):null;
        private static ReportSourceRef RestoreReportSource(ReportSaveData x){var kind=(ReportSourceKind)x.SourceKind;if(kind==ReportSourceKind.Caravan)return ReportSourceRef.Caravan(CaravanId.Create(x.SourceId));if(kind==ReportSourceKind.CityInstitution)return ReportSourceRef.Institution(CityId.Create(x.SourceCityId),CityBuildingId.Create(x.SourceBuildingId));return ReportSourceRef.Character(kind,CharacterId.Create(x.SourceId));}
    }
}
